        "model_state": checkpoint.get("model_state", checkpoint.get("model_state_dict")),
        "optimizer_state": checkpoint.get("optimizer_state", checkpoint.get("optimizer_state_dict")),
        "epoch": checkpoint.get("epoch", -1),
